css:
@font-face { font-family: 'ShunxiGalaxySong'; src: local('SourceHanSerifSC-Regular'), local('SourceHanSerifCN-Regular'), url('https://raw.githubusercontent.com/adobe-fonts/source-han-serif/release/SubsetOTF/CN/SourceHanSerifCN-Regular.otf') format('opentype'); font-weight: 400; font-style: normal; font-display: swap; }
.prose-chapter { container-type: inline-size; position: relative; isolation: isolate; overflow: hidden; width: 100%; max-width: 46em; min-width: 0; margin: 0 auto; padding: calc(33.333333% + 12px) 10% 20%; border: 0; border-radius: 0; background: #000000; color: var(--reader-ink); font-family: var(--reader-font); font-size: var(--reader-size); font-weight: 400; font-style: normal; line-height: var(--reader-leading); box-shadow: none; }
.prose-chapter::before, .prose-chapter::after { content: ''; position: absolute; left: 0; width: 100%; aspect-ratio: 3 / 1; background-size: 100% auto; background-repeat: no-repeat; background-position: center; pointer-events: none; z-index: -1; }
.prose-chapter::before { top: 0; background-image: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/shunxi/startop.png'); }
.prose-chapter::after { bottom: -6cqw; background-image: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/shunxi/starbottom.png'); }
.prose-title { position: relative; margin: 0 0 6.5cqw; padding: 0; color: #E3E9F3; font-family: inherit; font-size: 28px; line-height: 1.5; font-weight: 400; letter-spacing: .13em; text-indent: .13em; text-align: center; overflow-wrap: anywhere; text-shadow: 0 0 16px #9BB7E520; }
.prose-title::after { content: '────  ✦  ────'; display: block; white-space: pre; margin-top: .08em; color: #AEB9C9; font-family: inherit; font-size: 13px; font-weight: 400; line-height: 1.8; letter-spacing: .22em; text-indent: .22em; }
.paragraph { position: relative; margin: 0 0 1em; padding: 0; font-family: inherit; font-size: inherit; line-height: inherit; font-weight: 400; letter-spacing: .045em; text-indent: 0; text-align: left; overflow-wrap: anywhere; }
.paragraph:last-of-type { margin-bottom: 0; }
.paragraph q, .paragraph .prose-quote { color: #92BBF0; background: transparent; quotes: none; font-weight: inherit; font-style: inherit; text-decoration: none; }
.paragraph strong { color: #F3F5F9; font-weight: 700; }
.paragraph em { color: #DDE3ED; font-style: italic; }
.paragraph del { color: #AFB6C2; font-size: .88em; text-decoration: line-through; text-decoration-thickness: 1px; text-decoration-color: #C8D0DD; }
.paragraph code { font-family: inherit; font-size: .82em; color: #B7BFCC; background: none; border: 0; padding: 0; }
@media (max-width: 400px) { .prose-chapter { padding: calc(33.333333% + 12px) 8% 24%; } .paragraph { letter-spacing: .025em; margin-bottom: 1.25em; } .paragraph:last-of-type { margin-bottom: 0; } .prose-title { margin-bottom: 8cqw; } }
